        for (int i = 0; i < testCases.length; i++) {
            int[] arr = testCases[i];
            int[] arrCopy = arr.clone();

            // 测试返回新数组版本
            int[] sorted = quickSort(arr);
            System.out.printf("\n测试 %d: %s%n", i + 1, arrayToString(arr));
